import { pesquisarAcervo } from './provedores/agregador.js';
const $=(s,r=document)=>r.querySelector(s);
const escapar=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seguro=u=>{try{const x=new URL(u,location.origin);return['http:','https:'].includes(x.protocol)?x.href:''}catch{return''}};
const linksOficiais={camara:'https://dadosabertos.camara.leg.br/',senado:'https://www12.senado.leg.br/dados-abertos/',stf:'https://portal.stf.jus.br/',cnj:'https://www.cnj.jus.br/sistemas/datajud/api-publica/'};
let dialogo,area,statusAtual='estudar';
function criar(){if($('#observatorio-politico'))return;const nav=$('.navegacao'),ref=$('#abrir-constelacao')||$('#abrir-idiomas');const b=document.createElement('button');b.id='abrir-observatorio-politico';b.innerHTML='<span>↳</span>Observatório Político <small>TESTES</small>';ref?.before(b);dialogo=document.createElement('dialog');dialogo.id='observatorio-politico';dialogo.className='busca-modal observatorio-politico';dialogo.innerHTML=`<div class="cabecalho-modal"><a href="#inicio" class="marca-pequena" data-fechar-observatorio>BIBLIOTECA LIVRE · OBSERVATÓRIO POLÍTICO</a><button class="fechar" data-fechar-observatorio aria-label="Fechar">×</button></div><div class="observatorio-corpo"><header class="observatorio-abertura"><p class="rotulo">DADOS OFICIAIS · ESTUDO · LEGISLAÇÃO · JUSTIÇA</p><h2>Entenda antes de <em>julgar.</em></h2><p>Esta área reúne materiais de estudo e registros públicos. Ela não recomenda candidatos nem transforma acusação, investigação ou processo em condenação.</p></header><nav class="observatorio-abas" aria-label="Áreas do observatório"><button data-obs-aba="estudar" class="ativo">Estudar</button><button data-obs-aba="parlamentares">Parlamentares</button><button data-obs-aba="leis">Leis & projetos</button><button data-obs-aba="justica">Justiça & constitucionalidade</button></nav><section id="observatorio-conteudo" class="observatorio-conteudo"></section><footer class="observatorio-fontes"><span>Fontes oficiais e acadêmicas</span><a href="${linksOficiais.camara}" target="_blank" rel="noopener noreferrer">Câmara</a><a href="${linksOficiais.senado}" target="_blank" rel="noopener noreferrer">Senado</a><a href="${linksOficiais.stf}" target="_blank" rel="noopener noreferrer">STF</a><a href="${linksOficiais.cnj}" target="_blank" rel="noopener noreferrer">CNJ/DataJud</a></footer></div>`;document.body.append(dialogo);area=$('#observatorio-conteudo');b.addEventListener('click',abrir);dialogo.querySelectorAll('[data-fechar-observatorio]').forEach(x=>x.addEventListener('click',()=>dialogo.close()));dialogo.addEventListener('click',e=>{if(e.target===dialogo)dialogo.close()});dialogo.querySelectorAll('[data-obs-aba]').forEach(x=>x.addEventListener('click',()=>mostrar(x.dataset.obsAba)));mostrar('estudar')}
function abrir(){if(!dialogo)criar();if(!dialogo.open)dialogo.showModal()}
function ativar(nome){statusAtual=nome;dialogo.querySelectorAll('[data-obs-aba]').forEach(x=>x.classList.toggle('ativo',x.dataset.obsAba===nome))}
function carregando(texto){area.innerHTML=`<div class="obs-carregando"><span></span><strong>${escapar(texto)}</strong></div>`}
function mostrar(nome){ativar(nome);if(nome==='estudar')estudar();if(nome==='parlamentares')parlamentares();if(nome==='leis')leis();if(nome==='justica')justica()}
function estudar(){area.innerHTML=`<div class="obs-grade-estudo"><div class="obs-intro"><span class="rotulo">FORMAÇÃO POLÍTICA</span><h3>Estude o tema antes de acompanhar a disputa.</h3><p>Pesquise ciência política, democracia, Estado, políticas públicas, relações internacionais, economia política, sistemas eleitorais, constitucionalismo ou outro assunto.</p><form id="form-estudo-politica" class="obs-form"><input id="campo-estudo-politica" type="search" placeholder="Ex.: reforma agrária, federalismo, democracia…"><button class="primario">Buscar materiais</button></form></div><div id="resultado-estudo-politica" class="obs-resultados"><div class="obs-vazio">Livros, apostilas, textbooks e artigos abertos encontrados pela própria Biblioteca Livre aparecerão aqui.</div></div></div>`;$('#form-estudo-politica')?.addEventListener('submit',async e=>{e.preventDefault();const q=$('#campo-estudo-politica').value.trim();if(!q)return;const r=$('#resultado-estudo-politica');r.innerHTML='<div class="obs-vazio">Pesquisando materiais abertos…</div>';try{const d=await pesquisarAcervo(q,{pagina:1,fontesAtivas:['openalex','openlibrary','opentextbook','pressbooks','doab','oapen']});const livros=(d.livros||[]).slice(0,18);r.innerHTML=livros.length?livros.map(l=>`<article class="obs-linha"><div><small>${escapar(l.provedor||'Fonte aberta')}</small><h4>${escapar(l.titulo)}</h4><p>${escapar((l.autores||[]).join(' · ')||'Autoria informada pela fonte')}</p></div>${l.ler?`<a href="${escapar(seguro(l.ler))}" target="_blank" rel="noopener noreferrer">Abrir ↗</a>`:''}</article>`).join(''):'<div class="obs-vazio">Nenhum material apareceu nesta busca.</div>'}catch{r.innerHTML='<div class="obs-vazio">As fontes acadêmicas não responderam nesta tentativa.</div>'}})}
function parlamentares(){area.innerHTML=`<div class="obs-dividido"><section><span class="rotulo">CÂMARA DOS DEPUTADOS</span><h3>Perfil parlamentar documentado</h3><form id="form-politico" class="obs-form"><input id="campo-politico" type="search" placeholder="Nome de deputada ou deputado"><button class="primario">Pesquisar</button></form><div id="lista-politicos" class="obs-resultados"></div></section><aside id="ficha-politico" class="obs-ficha"><h3>Selecione um parlamentar</h3><p>O perfil mostrará mandato atual, partido/UF, despesas registradas e proposições de autoria disponíveis na fonte oficial.</p><div class="obs-alerta">Histórico judicial aparece separadamente e nunca é tratado como prova automática de crime.</div></aside></div>`;$('#form-politico')?.addEventListener('submit',async e=>{e.preventDefault();const q=$('#campo-politico').value.trim();if(!q)return;const lista=$('#lista-politicos');lista.innerHTML='<div class="obs-vazio">Consultando a Câmara…</div>';try{const d=await(await fetch(`/api/observatorio-politico?modo=deputados&nome=${encodeURIComponent(q)}`)).json();const itens=d.dados||[];lista.innerHTML=itens.length?itens.map(x=>`<button class="obs-politico" data-deputado="${x.id}"><img src="${escapar(seguro(x.urlFoto))}" alt="" loading="lazy"><span><strong>${escapar(x.nome)}</strong><small>${escapar(x.siglaPartido||'')} · ${escapar(x.siglaUf||'')}</small></span></button>`).join(''):'<div class="obs-vazio">Nenhum deputado encontrado com esse nome.</div>';lista.querySelectorAll('[data-deputado]').forEach(x=>x.addEventListener('click',()=>carregarDeputado(x.dataset.deputado)))}catch{lista.innerHTML='<div class="obs-vazio">A Câmara não respondeu nesta tentativa.</div>'}})}
async function carregarDeputado(id){const ficha=$('#ficha-politico');ficha.innerHTML='<div class="obs-vazio">Carregando registro oficial…</div>';try{const d=await(await fetch(`/api/observatorio-politico?modo=deputado&id=${id}`)).json(),p=d.perfil||{},u=p.ultimoStatus||{},despesas=d.despesas||[],props=d.proposicoes||[];const total=despesas.reduce((s,x)=>s+Number(x.valorLiquido||0),0);ficha.innerHTML=`<div class="obs-perfil"><div><span class="rotulo">REGISTRO OFICIAL DA CÂMARA</span><h3>${escapar(u.nome||p.nomeCivil||'Parlamentar')}</h3><p>${escapar(u.siglaPartido||'')} · ${escapar(u.siglaUf||'')} ${u.situacao?`· ${escapar(u.situacao)}`:''}</p></div>${u.urlFoto?`<img src="${escapar(seguro(u.urlFoto))}" alt="">`:''}</div><div class="obs-metricas"><div><small>Amostra de despesas ${d.ano}</small><strong>${total.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</strong></div><div><small>Proposições listadas</small><strong>${props.length}</strong></div></div><h4>Proposições recentes</h4><div class="obs-mini-lista">${props.slice(0,8).map(x=>`<button data-prop="${x.id}"><b>${escapar(`${x.siglaTipo||''} ${x.numero||''}/${x.ano||''}`)}</b><span>${escapar(x.ementa||'Sem ementa')}</span></button>`).join('')||'<p>Nenhuma proposição retornada.</p>'}</div><div class="obs-judicial-chamada"><strong>Histórico judicial público</strong><p>Para evitar falsas acusações, a Biblioteca não atribui processos pelo nome automaticamente. Use a área Justiça com um número processual oficial ou consulte o STF diretamente pelo nome da parte.</p><button data-ir-justica>Ir para Justiça & constitucionalidade</button><a href="${linksOficiais.stf}" target="_blank" rel="noopener noreferrer">Consultar STF ↗</a></div>`;ficha.querySelectorAll('[data-prop]').forEach(x=>x.addEventListener('click',()=>{mostrar('leis');setTimeout(()=>carregarProposicao(x.dataset.prop),0)}));ficha.querySelector('[data-ir-justica]')?.addEventListener('click',()=>mostrar('justica'))}catch{ficha.innerHTML='<div class="obs-vazio">Não foi possível carregar o perfil oficial.</div>'}}
function leis(){area.innerHTML=`<div class="obs-dividido"><section><span class="rotulo">PROJETOS E PROPOSIÇÕES</span><h3>Do texto à tramitação</h3><form id="form-leis" class="obs-form"><input id="campo-leis" type="search" placeholder="Ex.: reforma tributária, educação, meio ambiente…"><button class="primario">Pesquisar</button></form><div id="lista-leis" class="obs-resultados"></div></section><aside id="ficha-lei" class="obs-ficha"><h3>Situação constitucional</h3><p>A Biblioteca só exibirá “constitucional” ou “inconstitucional” quando houver decisão oficial identificada. Projeto de lei, ação proposta e decisão definitiva são coisas diferentes.</p><div class="obs-estado-constitucional neutro">Nenhuma decisão vinculada nesta consulta.</div><a href="${linksOficiais.stf}" target="_blank" rel="noopener noreferrer">Pesquisar ações no STF ↗</a></aside></div>`;$('#form-leis')?.addEventListener('submit',async e=>{e.preventDefault();const q=$('#campo-leis').value.trim();if(!q)return;const l=$('#lista-leis');l.innerHTML='<div class="obs-vazio">Consultando proposições…</div>';try{const d=await(await fetch(`/api/observatorio-politico?modo=proposicoes&q=${encodeURIComponent(q)}`)).json(),itens=d.dados||[];l.innerHTML=itens.length?itens.map(x=>`<button class="obs-proposicao" data-prop="${x.id}"><small>${escapar(`${x.siglaTipo||''} ${x.numero||''}/${x.ano||''}`)}</small><strong>${escapar(x.ementa||'Sem ementa')}</strong></button>`).join(''):'<div class="obs-vazio">Nenhuma proposição encontrada.</div>';l.querySelectorAll('[data-prop]').forEach(x=>x.addEventListener('click',()=>carregarProposicao(x.dataset.prop)))}catch{l.innerHTML='<div class="obs-vazio">A fonte legislativa não respondeu.</div>'}})}
async function carregarProposicao(id){const ficha=$('#ficha-lei');if(!ficha)return;ficha.innerHTML='<div class="obs-vazio">Carregando tramitação oficial…</div>';try{const d=await(await fetch(`/api/observatorio-politico?modo=proposicao&id=${id}`)).json(),x=d.detalhe||{},aut=d.autores||[],tr=(d.tramitacoes||[]).slice(-8).reverse();ficha.innerHTML=`<span class="rotulo">${escapar(`${x.siglaTipo||''} ${x.numero||''}/${x.ano||''}`)}</span><h3>${escapar(x.ementa||'Proposição')}</h3><p>${escapar(x.descricaoTipo||'')}</p><div class="obs-autores"><b>Autoria</b><span>${escapar(aut.map(a=>a.nome).filter(Boolean).join(' · ')||'Não informada')}</span></div><h4>Tramitação recente</h4><div class="obs-timeline">${tr.map(t=>`<div><time>${escapar((t.dataHora||'').slice(0,10))}</time><p>${escapar(t.descricaoSituacao||t.descricaoTramitacao||'Movimentação')}</p></div>`).join('')||'<p>Sem tramitações retornadas.</p>'}</div><div class="obs-estado-constitucional neutro"><b>Situação constitucional:</b> ainda não determinada automaticamente. A existência de ADI, ADC ou ADPF não equivale, por si só, a uma declaração de inconstitucionalidade.</div><a href="${linksOficiais.stf}" target="_blank" rel="noopener noreferrer">Verificar no STF ↗</a>`}catch{ficha.innerHTML='<div class="obs-vazio">Não foi possível carregar esta proposição.</div>'}}
function justica(){area.innerHTML=`<div class="obs-dividido"><section><span class="rotulo">CNJ · DATAJUD</span><h3>Consultar processo público por número oficial</h3><p>Use o número CNJ de um processo já identificado. A consulta não presume que uma pessoa seja culpada.</p><form id="form-processo" class="obs-form obs-form-processo"><select id="tribunal-processo"><option value="stj">STJ</option><option value="tse">TSE</option><option value="tst">TST</option><option value="trf1">TRF1</option><option value="trf2">TRF2</option><option value="trf3">TRF3</option><option value="trf4">TRF4</option><option value="trf5">TRF5</option><option value="trf6">TRF6</option><option value="tjsp">TJSP</option><option value="tjrj">TJRJ</option><option value="tjmg">TJMG</option><option value="tjes">TJES</option><option value="tjrs">TJRS</option></select><input id="numero-processo" type="search" placeholder="Número CNJ do processo"><button class="primario">Consultar</button></form><div id="resultado-processo" class="obs-resultados"></div></section><aside class="obs-ficha"><span class="rotulo">CONTROLE DE CONSTITUCIONALIDADE</span><h3>Como a Biblioteca vai rotular uma lei</h3><div class="obs-legenda"><div><b>Questionada</b><span>Existe ação constitucional localizada, sem concluir o mérito.</span></div><div><b>Decisão liminar</b><span>Há decisão provisória registrada.</span></div><div><b>Declarada inconstitucional</b><span>Somente quando o STF assim decidir, indicando o alcance.</span></div><div><b>Declarada constitucional</b><span>Somente quando houver decisão oficial correspondente.</span></div><div><b>Decisão parcial</b><span>Quando apenas dispositivos ou interpretações forem afetados.</span></div></div><a href="${linksOficiais.stf}" target="_blank" rel="noopener noreferrer">Consulta oficial do STF ↗</a></aside></div>`;$('#form-processo')?.addEventListener('submit',async e=>{e.preventDefault();const t=$('#tribunal-processo').value,n=$('#numero-processo').value.trim(),r=$('#resultado-processo');if(!n)return;r.innerHTML='<div class="obs-vazio">Consultando metadados processuais…</div>';try{const d=await(await fetch(`/api/observatorio-politico?modo=processo&tribunal=${encodeURIComponent(t)}&numero=${encodeURIComponent(n)}`)).json(),itens=d.dados||[];r.innerHTML=itens.length?itens.map(p=>`<article class="obs-processo"><small>${escapar(p.tribunal)} · ${escapar(p.grau||'grau não informado')}</small><h4>${escapar(p.numeroProcesso)}</h4><p>${escapar(p.classe?.nome||p.classe?.codigo||'Classe não informada')}</p><div class="obs-assuntos">${(p.assuntos||[]).slice(0,8).map(a=>`<span>${escapar(a.nome||a.codigo||'Assunto')}</span>`).join('')}</div>${p.indicadores?.encontrados?.length?`<div class="obs-movimentos-sensiveis"><b>Movimentações que exigem leitura do processo</b>${p.indicadores.encontrados.map(i=>`<span>${escapar(i.texto)}</span>`).join('')}<small>Isto descreve movimentações do processo, não uma conclusão independente da Biblioteca sobre a pessoa.</small></div>`:''}</article>`).join(''):'<div class="obs-vazio">Nenhum processo localizado neste tribunal com esse número.</div>'}catch{r.innerHTML='<div class="obs-vazio">O DataJud não respondeu nesta tentativa.</div>'}})}
criar();
window.BibliotecaObservatorioPolitico={abrir,mostrar};
